import java.io.*;

public class fivedimpoints {
    static int n;
    static int[][] coord;
    static boolean[] bad;
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));

    static int nextInt() throws IOException {
        int c = in.read();
        while (c != -1 && c <= ' ') c = in.read();
        if (c == -1) throw new IOException("EOF");
        int sign = 1;
        if (c == '-' || c == '+') {
            if (c == '-') sign = -1;
            c = in.read();
        }
        int val = 0;
        while (c != -1 && c > ' ') {
            val = val * 10 + (c - '0');
            c = in.read();
        }
        return val * sign;
    }

    public static void main(String[] args) throws IOException {
        n = nextInt();
        if (n > 11) {
            System.out.println(0);
            return;
        }
        coord = new int[n][5];
        bad = new boolean[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 5; j++) {
                coord[i][j] = nextInt();
            }
        }
        int count = n;
        outer:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (j == i) continue;
                for (int k = 0; k < n; k++) {
                    if (k == i || k == j) continue;
                    long prod = 0;
                    for (int m = 0; m < 5; m++) {
                        prod += (long) (coord[j][m] - coord[i][m]) * (coord[k][m] - coord[i][m]);
                    }
                    if (prod > 0) {
                        bad[i] = true;
                        count--;
                        continue outer;
                    }
                }
            }
        }
        System.out.println(count);
        for (int i = 0; i < n; i++) {
            if (!bad[i]) System.out.println(i + 1);
        }
    }
}
